 const completed=state.jobs.filter(x=>x.status==='Completed').length,billed=state.jobs.reduce((s,x)=>s+Number(x.bill_amount||0),0),paid=state.jobs.reduce((s,x)=>s+Number(x.paid_amount||0),0);
