function jobsTable(rows){if(!rows.length)return '<div class="empty">No work records found.</div>';return `<div class="table-wrap"><table><thead><tr><th>Estimate</th><th>Work description</th><th>Technical Assistant</th><th>Gram Panchayat</th><th>Received</th><th>Bill amount</th><th>Work status</th><th>Payment status</th><th></th></tr></thead><tbody>${rows.map(x=>{const due=Math.max(0,Number(x.bill_amount||0)-Number(x.paid_amount||0));return `<tr><td>${esc(x.estimate_number||'—')}</td><td><b>${esc(x.work_name)}</b></td><td>${esc(x.ta_name)}<br><small>${esc(x.block_name)}</small></td><td>${esc(x.gp_name||'—')}</td><td>${esc(x.received_date||'—')}</td><td>${money(x.bill_amount)}</td><td><span class="pill ${x.status==='Completed'?'done':''}">${esc(x.status)}</span></td><td><span class="pill ${due===0?'done':'neutral'}">${due===0?'Paid':due<Number(x.bill_amount)?'Part paid':'Unpaid'}</span></td><td><div class="work-pdf-actions">${x.pdf_storage_path?'<button class="small-btn" type="button" data-download-work-pdf="'+x.id+'">Download PDF</button>':'<span class="hint">No PDF</span>'}<label class="small-btn pdf-upload-label"> ${x.pdf_storage_path?'Replace PDF':'Upload PDF'}<input type="file" accept="application/pdf,.pdf" data-upload-work-pdf="${x.id}" hidden></label><button class="small-btn" data-edit-job="${x.id}">Edit</button></div></td></tr>`}).join('')}</tbody></table></div>`}
function parseVillages(value){
 const normalize=(item)=>{
  if(item && typeof item==='object')return {code:String(item.code||item.gp_code||''),name:String(item.name||item.gp_name||'')};
  const line=String(item||'').trim();
  if(!line)return null;
  // Legacy database stores mappings as "UP145367 - AALAPUR".
  const match=line.match(/^([A-Z]{2}\d{4,})\s*(?:[-–—|])\s*(.+)$/i);
  if(match)return {code:match[1].toUpperCase(),name:match[2].trim()};
  const parts=line.split(/\s*\|\s*/);
  if(parts.length>1)return {code:parts.shift().trim(),name:parts.join(' | ').trim()};
  return {code:'',name:line};
 };
 if(Array.isArray(value))return value.map(normalize).filter(Boolean);
 if(value && typeof value==='object')return [normalize(value)].filter(Boolean);
 const raw=String(value||'').trim();
 if(!raw)return [];
 try{
  const parsed=JSON.parse(raw);
  if(Array.isArray(parsed))return parsed.map(normalize).filter(Boolean);
  if(parsed && typeof parsed==='object')return [normalize(parsed)].filter(Boolean);
 }catch(_e){}
 return raw.split(/\r?\n/).map(normalize).filter(Boolean);
}
