 $('#addProfile').onclick=()=>openRecord('profile');$('#taLoginForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const {error}=await sb.rpc('assign_ta_login',{p_user_id:f.user_id.trim(),p_client_id:Number(f.client_id)});if(error){notify(error.message,true);return}notify('TA login linked successfully. The user must sign in again to receive the assigned read-only role.');e.target.reset()};
