 shell('Work Site Submission','<div class="submission-layout"><div class="panel submission-form-panel"><div class="panel-head"><h3>Submit completed work site details</h3><span class="pill done">TA submission</span></div><p class="hint">Submit one work site at a time. Your submission is sent directly to the administration dashboard for review.</p><form id="siteSubmissionForm" class="form-grid"><label class="field full-row">Gram Panchayat<select name="gp_name" required><option value="">Select your assigned Gram Panchayat</option>'+gps.map(g=>'<option>'+esc(g)+'</option>').join('')+'</select></label><label class="field full-row">Work name<input name="work_name" maxlength="250" placeholder="Enter work name" required></label><label class="field full-row">Measurement<input name="measurement" maxlength="500" placeholder="Example: 120 m × 3 m × 0.15 m" required></label><label class="field full-row">Work description<textarea name="description" rows="5" maxlength="5000" placeholder="Describe the completed work and location details…" required></textarea></label><label class="field full-row">Work-site photo<input name="site_image" type="file" accept="image/jpeg,image/png,image/webp" required><small class="hint">Choose a photo from your gallery or take a new photo with your camera · JPG, PNG or WebP · maximum 10 MB</small></label><div class="field full-row"><button class="primary" type="submit">Submit work details</button></div></form></div><div class="panel"><h3>My submitted work</h3><div id="mySubmissionList">'+(state.submissions.map(s=>'<div class="submission-history"><b>'+esc(s.work_name)+'</b><span>'+esc(s.gp_name)+'</span><small>'+esc(s.status)+' · '+new Date(s.created_at).toLocaleString('en-IN')+'</small></div>').join('')||'<div class="empty">No work submitted yet.</div>')+'</div></div></div>');
