async function populateAdminSubmissionList(target,rows){
 const box=$(target);if(!box)return;if(!rows.length){box.innerHTML='<div class="empty">No TA work submissions yet.</div>';return}
 const cards=await Promise.all(rows.map(async s=>{const url=await signedSubmissionImage(s.site_image_path);return '<article class="submission-card"><div class="submission-photo">'+(url?'<a href="'+esc(url)+'" target="_blank" rel="noopener"><img src="'+esc(url)+'" alt="Work site photo"></a>':'<div class="empty">Photo unavailable</div>')+'</div><div class="submission-details"><div class="submission-heading"><b>'+esc(s.work_name)+'</b><span class="pill '+(s.status==='Approved'?'done':'neutral')+'">'+esc(s.status)+'</span></div><p><b>Technical Assistant:</b> '+esc(s.ta_name)+' · <b>Gram Panchayat:</b> '+esc(s.gp_name)+'</p><p><b>Measurement:</b> '+esc(s.measurement)+'</p><p><b>Description:</b><br>'+esc(s.description).replace(/\n/g,'<br>')+'</p><small class="hint">Submitted '+new Date(s.created_at).toLocaleString('en-IN')+(s.work_tracker_id?' · Work Tracker ID '+s.work_tracker_id:'')+'</small>'+(s.status==='Submitted'?'<div class="submission-review"><label class="field">Final work name<input id="finalName-'+s.id+'" value="'+esc(s.work_name)+'" maxlength="250" required></label><label class="field">Work bill amount (₹)<input id="billAmount-'+s.id+'" type="number" min="0.01" step="0.01" value="300" required></label><label class="field">Attach estimate / work PDF (optional)<input id="approvePdf-'+s.id+'" type="file" accept="application/pdf,.pdf"></label><div class="submission-actions"><button class="primary small-btn" data-approve-submission="'+s.id+'">Approve & add to Work Tracker</button><button class="secondary small-btn" data-reject-submission="'+s.id+'">Reject</button></div></div>':(s.admin_work_name?'<p><b>Final work name:</b> '+esc(s.admin_work_name)+'</p>':''))+'</div></article>'}));
 box.innerHTML=cards.join('');
 box.querySelectorAll('[data-approve-submission]').forEach(btn=>btn.onclick=async()=>{const id=Number(btn.dataset.approveSubmission),name=$('#finalName-'+id)?.value.trim(),amount=Number($('#billAmount-'+id)?.value),pdf=$('#approvePdf-'+id)?.files?.[0];if(!name||!Number.isFinite(amount)||amount<=0){notify('Enter a final work name and a positive bill amount.',true);return}if(pdf&&(pdf.type!=='application/pdf'&&!pdf.name.toLowerCase().endsWith('.pdf'))){notify('Please select a PDF file.',true);return}if(pdf&&pdf.size>25*1024*1024){notify('PDF must be 25 MB or smaller.',true);return}btn.disabled=true;let uploadedPath=null;if(pdf){const safeName=pdf.name.replace(/[^a-zA-Z0-9._-]/g,'_').slice(-100)||'estimate.pdf';uploadedPath='pending-'+id+'/'+crypto.randomUUID()+'-'+safeName;const up=await sb.storage.from('estimates').upload(uploadedPath,pdf,{contentType:'application/pdf',upsert:false});if(up.error){btn.disabled=false;notify('PDF upload failed: '+up.error.message,true);return}}const r=await sb.rpc('approve_ta_work_submission',{p_submission_id:id,p_final_work_name:name,p_bill_amount:amount});if(r.error){if(uploadedPath)await sb.storage.from('estimates').remove([uploadedPath]);btn.disabled=false;notify(r.error.message,true);return}if(uploadedPath){const link=await sb.from('work_tracker').update({pdf_storage_path:uploadedPath,pdf_filename:pdf.name}).eq('id',r.data);if(link.error){await sb.storage.from('estimates').remove([uploadedPath]);await loadAll();render();notify('Work approved as record '+r.data+', but PDF could not be linked: '+link.error.message,true);return}}await loadAll();render();notify('Approved and added to Work Tracker as record '+r.data+(pdf?' with PDF attached.':'.'));});
 box.querySelectorAll('[data-reject-submission]').forEach(btn=>btn.onclick=async()=>{const id=Number(btn.dataset.rejectSubmission);if(!confirm('Reject this work-site submission?'))return;const r=await sb.from('ta_work_submissions').update({status:'Rejected',reviewed_at:new Date().toISOString(),reviewed_by:state.user.id}).eq('id',id);if(r.error){notify(r.error.message,true);return}await loadAll();render();notify('Submission rejected.');});
}
