  const total=works.reduce((s,w)=>s+Number(w.bill_amount||0),0),allocated=works.reduce((s,w)=>s+Number(w.paid_amount||0),0),due=works.reduce((s,w)=>s+Math.max(0,Number(w.bill_amount||0)-Number(w.paid_amount||0)),0),periodPaid=payments.reduce((s,p)=>s+Number(p.amount||0),0);
