function paymentTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Technical Assistant</th><th>Received</th><th>Allocated</th><th>Mode</th><th>Reference</th><th>Operator</th></tr></thead><tbody>${rows.map(p=>{const allocations=state.allocations.filter(a=>Number(a.payment_id)===Number(p.id));const allocated=allocations.reduce((s,a)=>s+Number(a.amount||0),0);return `<tr><td>${esc(p.payment_date)}</td><td>${esc(p.ta_name)}</td><td>${money(p.amount)}</td><td>${allocations.length?`${money(allocated)} <small>· ${allocations.length} work(s)</small>`:'<span class="pill neutral">Legacy / unmapped</span>'}</td><td>${esc(p.payment_mode)}</td><td>${esc(p.reference_no||'—')}</td><td>${esc(p.depositing_operator)}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">No payments recorded.</div>'}
async function savePayment(e){e.preventDefault();if(!state.migrationReady){notify('Run supabase-improvements.sql in Supabase before recording payments.',true);return}const f=Object.fromEntries(new FormData(e.target));const amount=Number(f.amount);if(!Number.isFinite(amount)||amount<=0||Math.round(amount*100)!==amount*100){notify('Enter a valid positive amount with up to two decimal places.',true);return}if(f.payment_date>isoDateLocal()){notify('Payment date cannot be in the future.',true);return}const {data,error}=await sb.rpc('record_ta_payment',{p_ta_name:f.ta_name,p_amount:amount,p_payment_date:f.payment_date,p_payment_mode:f.payment_mode,p_reference_no:f.reference_no||null,p_depositing_operator:f.depositing_operator});if(error){notify(error.message,true);return}await loadAll();render();notify(`Payment recorded. ${money(data?.[0]?.allocated_amount??amount)} allocated to oldest outstanding works.`)}


