function updateEstimateMeasurementFields(){
 const type=$('#estType')?.value, schema=estimateMeasurementSchemas[type]||[];
 const host=$('#estMeasurements');if(!host)return;
 host.innerHTML=schema.map(([key,label])=>`<label class="field">${label}<input type="number" min="0" step="any" id="estMeasure_${key}" placeholder="Enter ${label.toLowerCase()}" required></label>`).join('');
}
function renderEstimate(){
 const gpNames=[...new Set(state.profiles.flatMap(p=>parseVillages(p.villages).map(v=>v.name)).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
 const typeOptions=estimateWorkTypes.map(g=>`<optgroup label="${g.group}">${g.items.map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</optgroup>`).join('');
 shell('Estimate Generator',`<div class="panel"><div class="panel-head"><h3>VB G-RAM-G project report generator</h3></div><p class="hint">Generate the project report body and forwarding note. Select the Gram Panchayat by name; internal mapping codes are not displayed.</p><div class="form-grid"><label class="field">Work category<select id="estType">${typeOptions}</select></label><label class="field">Block<select id="estBlock">${blocks.map(b=>`<option>${b}</option>`).join('')}</select></label><label class="field">Gram Panchayat<select id="estVillage" required><option value="">Select Gram Panchayat</option>${gpNames.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('')}</select></label><div id="estMeasurements" class="form-grid full-row"></div><label class="field">Estimated amount (₹)<input id="estAmount" placeholder="e.g. 6,95,123.00"></label></div><button class="primary" id="generateEstimate">Generate report</button></div><div id="estimateOutput"></div>`);
 $('#estType').addEventListener('change',updateEstimateMeasurementFields);updateEstimateMeasurementFields();$('#generateEstimate').onclick=generateEstimate;
}
function generateEstimate(){
 const type=$('#estType').value,block=$('#estBlock').value,amt=$('#estAmount').value.trim()||'Not specified',v=$('#estVillage').value.trim();
 if(!v){notify('Select a Gram Panchayat.',true);return}
 const schema=estimateMeasurementSchemas[type]||[],parts=[];
 for(const [key,label] of schema){const field=$('#estMeasure_'+key),value=field?.value.trim();if(!value||!Number.isFinite(Number(value))||Number(value)<=0){notify('Enter a valid value for '+label+'.',true);field?.focus();return}parts.push(label.replace(/\s*\([^)]*\)$/,'')+': '+value+(key==='nos'?' Nos.':' m'))}
 const m=parts.join(', '),workName=estimateWorkNames[type]||type,benefit=estimateWorkBenefits[type]||'benefit the local community';
 const report=`This estimate, prepared under the VB G-RAM-G scheme, is based on a directive from the Block Development Officer - ${block}. Following a physical inspection, the project involves ${workName} at Gram Panchayat ${v}. The work measurements are: ${m}. The work includes three-stage photographs and a signboard. This project will ${benefit}, and provide temporary employment opportunities for Job Card Holders. The estimated cost of Rs. ${amt} has been submitted for technical, financial, and administrative approval.`;
 const forward='Please see the attached for technical and administrative approval.';
 $('#estimateOutput').innerHTML=`<div class="panel"><h3>Project report body</h3><p class="output" id="reportText">${esc(report)}</p><button class="secondary" data-copy="reportText">Copy report</button></div><div class="panel"><h3>Forwarding note</h3><p class="output" id="forwardText">${esc(forward)}</p><button class="secondary" data-copy="forwardText">Copy note</button></div>`;
 document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>navigator.clipboard.writeText($('#'+b.dataset.copy).textContent).then(()=>notify('Copied to clipboard.')))
}
function formatVillagesForEditor(value){return parseVillages(value).map(v=>v.code?`${v.code} | ${v.name}`:v.name).join('\n')}
function normalizeProfileData(data){data.villages=JSON.stringify(parseVillages(data.villages));return data}
function openRecord(type,row=null){state.editing=row;const isProfile=type==='profile';$('#dialogTitle').textContent=(row?'Edit ':'Add ')+(isProfile?'TA profile':'work entry');let allGP=[...new Set(state.profiles.flatMap(p=>parseVillages(p.villages).map(v=>v.name)).filter(Boolean))].sort();let fields=isProfile?[['name','Full name','text',row?.name],['post','Post / designation','text',row?.post],['block','Block','select',row?.block,blocks],['phone','Phone','tel',row?.phone],['villages','Gram Panchayat mappings (one per line: CODE | NAME)','textarea',formatVillagesForEditor(row?.villages)]]:[['work_name','Work description','text',row?.work_name],['ta_name','Technical Assistant','select',row?.ta_name,state.profiles.map(p=>p.name)],['gp_name','Assigned Gram Panchayat','select',row?.gp_name,allGP],['received_date','Received date','date',row?.received_date||isoDateLocal()],['bill_amount','Bill amount (₹)','number',row?.bill_amount??300],['status','Work status','select','Completed',['Completed']]];$('#dialogFields').innerHTML=fields.map(([n,l,t,v,opts])=>`<label class="field ${t==='textarea'?'full-row':''}">${l}${t==='select'?`<select name="${n}" required><option value="">Select</option>${opts.map(o=>`<option ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select>`:t==='textarea'?`<textarea name="${n}" rows="3">${esc(v||'')}</textarea>`:`<input name="${n}" type="${t}" value="${esc(v??'')}" ${['name','work_name','ta_name','bill_amount'].includes(n)?'required':''}>`}</label>`).join('');if(!isProfile)$('#dialogFields').insertAdjacentHTML('beforeend','<label class="field full-row">Attach / replace work PDF (optional)<input id="editWorkPdf" type="file" accept="application/pdf,.pdf"><small class="hint">PDF only · maximum 25 MB. Leave empty to keep the current attachment.</small></label>');$('#recordDialog').showModal();if(!isProfile){const ta=$('#dialogFields [name="ta_name"]'),gp=$('#dialogFields [name="gp_name"]');const syncGP=()=>{const profile=state.profiles.find(p=>p.name===ta.value);const names=parseVillages(profile?.villages).map(v=>v.name);const legacy=row?.gp_name&&!names.includes(row.gp_name)?`<option selected>${esc(row.gp_name)}</option>`:'';gp.innerHTML='<option value="">Select assigned Gram Panchayat</option>'+legacy+names.map(n=>`<option ${n===row?.gp_name?'selected':''}>${esc(n)}</option>`).join('')};ta.addEventListener('change',syncGP);syncGP();}$('#recordForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(isProfile)await saveProfile(data,row);else await saveJob(data,row,$('#editWorkPdf')?.files?.[0]);}}
async function saveProfile(data,row){if(!data.name?.trim()||!data.block){notify('TA name and block are required.',true);return}if(row&&data.name.trim().toLowerCase()!==row.name.toLowerCase()&&(state.jobs.some(j=>j.ta_name===row.name)||state.payments.some(p=>p.ta_name===row.name))){notify('This TA has historical work or payment records. Renaming is blocked to protect those links.',true);return}data.name=data.name.trim();data=normalizeProfileData(data);const result=row?await sb.from('clients').update(data).eq('id',row.id):await sb.from('clients').insert(data).select('id').single();if(result.error){notify(result.error.message,true);return}$('#recordDialog').close();state.selectedProfileId=row?.id||result.data?.id||null;await loadAll();render();notify('Profile saved.')}
async function saveJob(data,row,pdfFile=null){if(pdfFile&&((pdfFile.type!=='application/pdf'&&!pdfFile.name.toLowerCase().endsWith('.pdf'))||pdfFile.size>25*1024*1024)){notify('Please select a valid PDF of 25 MB or smaller.',true);return}data.status='Completed';const profile=state.profiles.find(p=>p.name===data.ta_name);const assignmentChanged=!row||data.ta_name!==row.ta_name||data.gp_name!==row.gp_name;if(assignmentChanged&&!profile){notify('Select a valid Technical Assistant.',true);return}const allowedGP=parseVillages(profile?.villages).map(v=>v.name);if(assignmentChanged&&!allowedGP.includes(data.gp_name)){notify('Select a Gram Panchayat assigned to this Technical Assistant.',true);return}data.work_name=data.work_name.trim();data.block_name=profile?.block||row?.block_name||'';data.bill_amount=Number(data.bill_amount);data.received_date=data.received_date||null;if(!data.work_name||!Number.isFinite(data.bill_amount)||data.bill_amount<=0){notify('Work description and a positive bill amount are required.',true);return}if(row&&data.bill_amount<Number(row.paid_amount||0)){notify('Bill amount cannot be lower than payments already allocated.',true);return}let workId=row?.id;if(row){const result=await sb.from('work_tracker').update(data).eq('id',row.id);if(result.error){notify(result.error.message,true);return}}else{data.paid_amount=0;data.estimate_number='';const result=await sb.from('work_tracker').insert(data).select('id').single();if(result.error){notify(result.error.message,true);return}workId=result.data.id;const upd=await sb.from('work_tracker').update({estimate_number:'Est-'+String(workId).padStart(5,'0')}).eq('id',workId);if(upd.error){notify('Work saved but estimate number could not be assigned: '+upd.error.message,true);return}}if(pdfFile){const safeName=pdfFile.name.replace(/[^a-zA-Z0-9._-]/g,'_').slice(-100)||'estimate.pdf',path=workId+'/'+crypto.randomUUID()+'-'+safeName,up=await sb.storage.from('estimates').upload(path,pdfFile,{contentType:'application/pdf',upsert:false});if(up.error){notify('Work saved, but PDF upload failed: '+up.error.message,true);return}const linked=await sb.from('work_tracker').update({pdf_storage_path:path,pdf_filename:pdfFile.name}).eq('id',workId);if(linked.error){await sb.storage.from('estimates').remove([path]);notify('Work saved, but PDF could not be linked: '+linked.error.message,true);return}if(row?.pdf_storage_path)await sb.storage.from('estimates').remove([row.pdf_storage_path])}$('#recordDialog').close();await loadAll();render();notify('Work entry saved. Payment history and allocated amounts were preserved.'+(pdfFile?' PDF attached.':''))}

async function downloadWorkPdf(workId){
 const work=state.jobs.find(j=>Number(j.id)===Number(workId));
 if(!work?.pdf_storage_path){notify('No PDF is attached to this work record yet.',true);return}
 const {data,error}=await sb.storage.from('estimates').download(work.pdf_storage_path);
 if(error){notify('PDF download failed: '+error.message,true);return}
 const url=URL.createObjectURL(data),a=document.createElement('a');
 a.href=url;a.download=(work.estimate_number||'work-estimate')+'.pdf';
 document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-download-work-pdf]');
 if(b){e.preventDefault();downloadWorkPdf(Number(b.dataset.downloadWorkPdf));}
});
document.addEventListener('change',async e=>{
 const input=e.target.closest('[data-upload-work-pdf]');
 if(!input||!input.files?.length)return;
 const workId=Number(input.dataset.uploadWorkPdf),work=state.jobs.find(j=>Number(j.id)===workId),file=input.files[0];
 if(!work){notify('Work record not found.',true);input.value='';return}
 if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){notify('Please select a PDF file.',true);input.value='';return}
 if(file.size>25*1024*1024){notify('PDF must be 25 MB or smaller.',true);input.value='';return}
 input.disabled=true;
 const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,'_').slice(-100)||'estimate.pdf';
 const path=workId+'/'+crypto.randomUUID()+'-'+safeName;
 const upload=await sb.storage.from('estimates').upload(path,file,{contentType:'application/pdf',upsert:false});
 if(upload.error){input.disabled=false;input.value='';notify('PDF upload failed: '+upload.error.message,true);return}
 const saved=await sb.from('work_tracker').update({pdf_storage_path:path,pdf_filename:file.name}).eq('id',workId);
 if(saved.error){await sb.storage.from('estimates').remove([path]);input.disabled=false;input.value='';notify('PDF uploaded but could not be linked: '+saved.error.message,true);return}
 if(work.pdf_storage_path)await sb.storage.from('estimates').remove([work.pdf_storage_path]);
 await loadAll();render();notify('PDF attached to '+(work.estimate_number||'work record')+'.');
});

$('#closeDialog').onclick=$('#cancelDialog').onclick=()=>$('#recordDialog').close();
document.addEventListener('click',async e=>{const workEdit=e.target.closest('[data-edit-job]');if(workEdit){openRecord('job',state.jobs.find(j=>j.id===Number(workEdit.dataset.editJob)));return}const edit=e.target.closest('[data-edit-profile]');if(edit){openRecord('profile',state.profiles.find(p=>p.id===Number(edit.dataset.editProfile)));return}const del=e.target.closest('[data-delete-profile]');if(del){const profile=state.profiles.find(p=>p.id===Number(del.dataset.deleteProfile));if(state.jobs.some(j=>j.ta_name===profile?.name)||state.payments.some(p=>p.ta_name===profile?.name)){notify('This profile has financial or work history. Keep it for record integrity; it cannot be deleted.',true);return}if(confirm('Delete this TA profile?')){const {error}=await sb.from('clients').delete().eq('id',Number(del.dataset.deleteProfile));if(error)notify(error.message,true);else{await loadAll();render();notify('Profile deleted.')}}}});
